# Brute force best strategy
prices = {"Highcliff": {"wine":12,"salt":44,"amber":23,"iron":14},
          "Saltby": {"wine":41,"salt":10,"amber":27,"iron":28},
          "Oakhaven": {"wine":34,"salt":40,"amber":33,"iron":24}}
CAP, LAST = 30, 8
goods = list(prices["Highcliff"])

def best_from(day, town, gold, cargo):
    if day > LAST:
        return gold + sum(prices[town][g]*q for g,q in cargo.items())
    best = best_from(day+1, town, gold, cargo)  # stay
    for t2, p2 in prices.items():
        if t2 == town: continue
        # buy optimally: try all combos
        for g in goods:
            for q in range(0, CAP - sum(cargo.values()) + 1):
                if p2 and gold >= prices[town][g]*q:
                    c2 = dict(cargo); c2[g] = cargo.get(g,0) + q
                    best = max(best, best_from(day+1, t2, gold - prices[town][g]*q, c2))
    return best

print(best_from(1, "Highcliff", 120, {}))
