from collections import defaultdict

prices = {"Highcliff": {"wine":12,"salt":44,"amber":23,"iron":14},
          "Saltby": {"wine":41,"salt":10,"amber":27,"iron":28},
          "Oakhaven": {"wine":34,"salt":40,"amber":33,"iron":24}}
CAP, LAST, GOOD = 30, 8, ["wine","salt","amber","iron"]
idx = {g:i for i,g in enumerate(GOOD)}

states = {("Highcliff",(0,0,0,0)): 120}
for day in range(1, LAST+1):
    cur = dict(states)
    # buy up to 30 units of each good (one-unit-at-a-time loop keeps capacity/gold constraints)
    for g in GOOD:
        i = idx[g]
        for _ in range(CAP):
            nxt = defaultdict(lambda: -1)
            for (t2, c2), g2 in cur.items():
                if sum(c2) < CAP and g2 >= prices[t2][g]:
                    c = list(c2); c[i] += 1
                    nxt[(t2, tuple(c))] = max(nxt[(t2, tuple(c))], g2 - prices[t2][g])
            for k, v in nxt.items():
                cur[k] = max(cur[k], v)
    new = defaultdict(lambda: -1)
    for (t2, c2), g2 in cur.items():
        sold = g2 + sum(prices[t2][GOOD[i]]*c2[i] for i in range(4))
        new[(t2,(0,0,0,0))] = max(new[(t2,(0,0,0,0))], sold)      # sell everything
        for t3 in prices:                                           # travel with cargo
            if t3 != t2:
                new[(t3, c2)] = max(new[(t3, c2)], g2)
        new[(t2, c2)] = max(new[(t2, c2)], g2)                      # stay with cargo
    states = new
    bestnow = max(v for v in states.values())
    bestwith = max(v + sum(prices[t][GOOD[i]]*c[i] for i in range(4)) for (t,c),v in states.items())
    print("day", day, "gold:", bestnow, "gold if sell all:", bestwith)
