# Clean exhaustive search over all (town, cargo-tuple) with max-gold DP.
# Cargo can be mixed. In a town: you may sell any subset, then buy any goods
# up to cart capacity and gold, then (if not last day) travel to another town.
from itertools import product
prices = {"Highcliff": {"wine":12,"salt":44,"amber":23,"iron":14},
          "Saltby": {"wine":41,"salt":10,"amber":27,"iron":28},
          "Oakhaven": {"wine":34,"salt":40,"amber":33,"iron":24}}
GOOD=["wine","salt","amber","iron"]
CAP,LAST=30,8
def val(t,c,g): return g+sum(prices[t][GOOD[i]]*c[i] for i in range(4))

def buy_fill(town,cargo,gold):
    # return set of (cargo,gold) reachable by buying (any goods, up to cap & gold)
    out={}
    space=CAP-sum(cargo)
    # enumerate all buy-amounts per good within remaining space
    for qw in range(space+1):
        for qs in range(space-qw+1):
            for qa in range(space-qw-qs+1):
                qi=space-qw-qs-qa
                cost=prices[town]["wine"]*qw+prices[town]["salt"]*qs+prices[town]["amber"]*qa+prices[town]["iron"]*qi
                if cost<=gold:
                    nc=(cargo[0]+qw,cargo[1]+qs,cargo[2]+qa,cargo[3]+qi)
                    out[nc]=max(out.get(nc,-1),gold-cost)
    return out

states={("Highcliff",(0,0,0,0)):120}
for day in range(1,LAST+1):
    nxt={}
    def add(t,c,g):
        k=(t,c)
        nxt[k]=max(nxt.get(k,-1),g)
    for (town,cargo),gold in states.items():
        # all sell subsets (each good sold fully or kept)
        for combo in product((0,1),repeat=4):
            c=list(cargo); g=gold
            for i in range(4):
                if combo[i]: g+=prices[town][GOOD[i]]*c[i]; c[i]=0
            c=tuple(c)
            # then buy to fill
            for nc,ng in buy_fill(town,c,g).items():
                add(town,nc,ng)
                if day<LAST:
                    for t2 in prices:
                        if t2!=town: add(t2,nc,ng)
    states=nxt
    print("day",day,"best value:",max(val(t,c,g) for (t,c),g in states.items()))
print("FINAL max gold:",max(val(t,c,g) for (t,c),g in states.items()))
# best cash-only (empty cart)
print("best with empty cart:",max(g for (t,c),g in states.items() if sum(c)==0))
