PRICES = {"Highcliff": {"amber":43,"copper":47,"timber":51,"silk":24},
          "Thornwick": {"amber":36,"copper":42,"timber":47,"silk":43},
          "Stonebridge": {"amber":8,"copper":35,"timber":9,"silk":10}}
CAP = 30
GOODS = ["amber","copper","timber","silk"]
gi = {g:i for i,g in enumerate(GOODS)}
towns = ["Highcliff","Thornwick","Stonebridge"]

# state: (town, gold, a, c, t, s)
reachable = {("Highcliff", 200, 0, 0, 0, 0)}

for day in range(1, 9):
    # closure under single-unit buys/sells (free, any number of them)
    changed = True
    while changed:
        changed = False
        for st in list(reachable):
            town, gold = st[0], st[1]
            prices = PRICES[town]
            cargo = st[2:]
            for g in GOODS:
                i = gi[g]
                # sell 1
                if cargo[i] > 0:
                    ns = (town, gold + prices[g],
                          cargo[0] - (i==0), cargo[1] - (i==1),
                          cargo[2] - (i==2), cargo[3] - (i==3))
                    if ns not in reachable:
                        reachable.add(ns); changed = True
                # buy 1
                if gold >= prices[g] and sum(cargo) < CAP:
                    ns = (town, gold - prices[g],
                          cargo[0] + (i==0), cargo[1] + (i==1),
                          cargo[2] + (i==2), cargo[3] + (i==3))
                    if ns not in reachable:
                        reachable.add(ns); changed = True
    if day < 8:
        reachable = {(t,) + st[1:] for st in reachable for t in towns if t != st[0]}
    print("day %2d: %4d states, max gold = %d" % (day, len(reachable), max(s[1] for s in reachable)))

print("FINAL MAX GOLD:", max(s[1] for s in reachable))
