from itertools import product

PRICES = {"Highcliff": {"amber":43,"copper":47,"timber":51,"silk":24},
          "Thornwick": {"amber":36,"copper":42,"timber":47,"silk":43},
          "Stonebridge": {"amber":8,"copper":35,"timber":9,"silk":10}}
CAP = 30
GOODS = ["amber","copper","timber","silk"]
TOWNS = ["Highcliff","Thornwick","Stonebridge"]
ti = {t:i for i,t in enumerate(TOWNS)}

# all cart vectors with total <= CAP
carts = [tuple(c) for c in product(range(CAP+1), repeat=4) if sum(c) <= CAP]
print("num cart vectors:", len(carts))

# state: dict keyed by (town, cart) -> max gold
state = {(0, (0,0,0,0)): 200}   # town index, cart tuple

for day in range(1, 9):
    # closure: trade at current town
    new = {}
    for (t, cart), gold in state.items():
        p = [PRICES[TOWNS[t]][g] for g in GOODS]
        wealth = gold + sum(ci*pi for ci, pi in zip(cart, p))
        new[(t, cart)] = max(new.get((t, cart), 0), gold)  # keep (may be improved by closure below)
    # per-town closure: for each town, compute best gold for each cart
    # max wealth achievable at town t from any source state in that town
    # gold'(c') = (max wealth W among source states with W >= cost(c')) - cost(c')
    by_town = {}
    for (t, cart), gold in new.items():
        by_town.setdefault(t, []).append((cart, gold))
    closed = {}
    for t, lst in by_town.items():
        p = [PRICES[TOWNS[t]][g] for g in GOODS]
        wealths = [g + sum(ci*pi for ci, pi in zip(cart, p)) for cart, g in lst]
        maxW = max(wealths)
        # best wealth available for each cost level
        bestW = {}
        for W in wealths:
            for cart, g in zip([c for c,_ in lst], [gg for _,gg in lst]):
                pass
        # simpler: cost values range 0..1530
        maxcost = 30*51
        arr = [0]*(maxcost+1)
        for W in wealths:
            if W > arr[W]:  # not right; need "for cost c: max W with W>=c"
                pass
        # do it with a max over wealths >= c: use a suffix max
        has = [False]*(maxcost+1)
        for W in wealths:
            has[min(W, maxcost)] = True
        sufmax = [0]*(maxcost+1)
        run = 0
        for c in range(maxcost, -1, -1):
            if has[c]: run = c
            sufmax[c] = max(run, sufmax[c+1] if c+1 <= maxcost else 0)
        # sufmax[c] = max W (capped at maxcost) among W >= c
        for cprime in carts:
            cost = sum(ci*pi for ci, pi in zip(cprime, p))
            if cost > 0 or True:
                if cost <= maxW:
                    g2 = sufmax[cost] - cost
                    if g2 < 0: continue
                    key = (t, cprime)
                    if g2 > closed.get(key, -1):
                        closed[key] = g2
    state = closed
    if day < 8:
        # travel: same cart/gold, different town
        moved = {}
        for (t, cart), gold in state.items():
            for t2 in range(3):
                if t2 != t:
                    key = (t2, cart)
                    if gold > moved.get(key, -1):
                        moved[key] = gold
        state = moved
    best = max(state.values())
    print("day %d: %4d states, max gold = %d" % (day, len(state), best))

print("FINAL MAX GOLD:", max(state.values()))
# show which town/cart achieves it
for (t, cart), g in state.items():
    if g == max(state.values()):
        print(" ", TOWNS[t], "cart", dict(zip(GOODS, cart)), "gold", g)
