GOODS = ["tea","grain","spice","iron"]
CAP, LAST = 25, 7
from functools import lru_cache
from itertools import product

def buy_vectors(space, gold, prices, idx=0, acc=()):
    """yield qty tuples for remaining goods, limited by space and gold"""
    if idx == 4:
        yield acc
        return
    p = prices[GOODS[idx]]
    maxq = min(space, gold // p) if p > 0 else space
    for q in range(maxq, -1, -1):
        for rest in buy_vectors(space - q, gold - q*p, prices, idx+1, acc + (q,)):
            yield rest

@lru_cache(maxsize=None)
def best(day, town, gold, cargo):
    p = PRICES[town]
    if day >= LAST:
        return gold + sum(q*p[g] for q,g in zip(cargo,GOODS))
    bestv = -1
    for s in product(*(range(c+1) for c in cargo)):
        gold2 = gold + sum(si*p[g] for si,g in zip(s,GOODS))
        space = CAP - sum(c-si for c,si in zip(cargo,s))
        for b in buy_vectors(space, gold2, p):
            if sum(b) > space: continue  # space check per-guaranteed below
            gold3 = gold2 - sum(bi*p[g] for bi,g in zip(b,GOODS))
            cargo2 = tuple(c - si + bi for c,si,bi in zip(cargo,s,b))
            for nt in TOWNS:
                if nt != town:
                    v = best(day+1, nt, gold3, cargo2)
                    if v > bestv: bestv = v
    return bestv

start = best(1, "Saltby", 120, (0,0,0,0))
print("max final gold:", start)
print(best.cache_info())
