from itertools import product
prices = {"Fennick": {"timber": 44, "salt": 26, "spice": 50, "fish": 33},
          "Highcliff": {"timber": 12, "salt": 21, "spice": 27, "fish": 10},
          "Thornwick": {"timber": 48, "salt": 21, "spice": 36, "fish": 9},
          "Dunmere": {"timber": 55, "salt": 60, "spice": 20, "fish": 18}}
goods = ["timber", "salt", "spice", "fish"]
cap = 40

def town_moves(town, gold, cargo):
    """Yield all (new_gold, new_cargo) reachable by selling and buying at this town."""
    results = [(gold, list(cargo))]
    for sell_flags in product([0,1], repeat=4):
        nc = list(cargo); ng = gold
        for i in range(4):
            if sell_flags[i]:
                ng += nc[i]*prices[town][goods[i]]; nc[i] = 0
        for buy_flags in product([0,1], repeat=4):
            nc2 = list(nc); ng2 = ng
            for i in range(4):
                if buy_flags[i]:
                    room = cap - sum(nc2)
                    b = min(room, ng2 // prices[town][goods[i]])
                    nc2[i] += b; ng2 -= b*prices[town][goods[i]]
            results.append((ng2, tuple(nc2)))
    return results

# states: (town, cargo) -> max gold; plus parents for reconstruction
state = {("Fennick", (0,0,0,0)): 250}
history = {}
for day in range(1, 8):
    new = {}
    for (town, cargo), gold in state.items():
        # stay: buy/sell in place
        for ng, nc in town_moves(town, gold, cargo):
            k = (town, nc)
            new[k] = max(new.get(k, -1), ng)
        # travel
        for t2 in prices:
            if t2 != town:
                k = (t2, cargo)
                new[k] = max(new.get(k, -1), gold)
    state = new
    print(f"day {day}: best = {max(state.values())}, states = {len(state)}")
    for k,v in sorted(state.items(), key=lambda x: -x[1])[:4]:
        print("   ", k, v)
best = max(state.values())
print("final best gold:", best)
