cap, last_day = 20, 8

# DP over (town, cargo) -> max gold, processing days.
# Each day: (a) optimal in-town trades, (b) optional travel.
# Value of a good at town t on day d = max price at towns reachable within (last_day - d) travels
def value(g, t, day):
    rem = last_day - day
    if rem == 0: return prices[t][g]
    reach = {t}
    cur = {t}
    for _ in range(rem):
        cur = set(u for u in towns for c in cur if True and u in towns)
        # all towns reachable in >=1 travel from any; with full connectivity:
    # with full connectivity & rem>=1: any town reachable? From t in k steps any town reachable (k>=1 for any of the 3 towns since it's a triangle)
    if rem >= 1:
        return max(prices[u][g] for u in towns)
    return prices[t][g]

def trade(gold, cargo, t, day):
    p = prices[t]
    # sell all goods worth more here than anywhere we'll go
    newc = dict(cargo); g2 = gold
    for g in goods:
        v = value(g, t, day)
        if p[g] > v:
            q = newc.get(g, 0); g2 += q * p[g]; newc[g] = 0
    # buy greedily by profit per unit
    room = cap - sum(newc.values())
    order = sorted([g for g in goods if p[g] < value(g, t, day)], key=lambda g: - (value(g,t,day) - p[g]))
    for g in order:
        q = min(room, g2 // p[g])
        g2 -= q * p[g]; newc[g] = newc.get(g, 0) + q; room -= q
    return g2, newc

# exhaustive BFS over states (day, town, cargo) -> max gold
best = {("Eastwatch", (0,0,0,0)): 250}
for day in range(1, last_day+1):
    new = {}
    for (t, cg), gold in best.items():
        cg = dict(zip(goods, cg))
        g2, nc = trade(gold, cg, t, day)
        nc = tuple(nc.get(g, 0) for g in goods)
        cand = {(t, nc): g2}
        if day < last_day:
            for u in towns:
                if u != t: cand[(u, nc)] = g2
        for k, v in cand.items():
            new[k] = max(new.get(k, -1), v)
    best = new
    print(day, "states:", len(best))
    if day == last_day:
        # final: sell everything locally
        final = 0
        for (t, cg), gold in best.items():
