from functools import lru_cache
prices = {"Eastwatch": {"fish":55,"silk":44,"timber":41,"amber":14},
          "Ashford":   {"fish":37,"silk":17,"timber":51,"amber":46},
          "Marlow":    {"fish":38,"silk":41,"timber":59,"amber":35}}
towns = list(prices); goods = ["fish","silk","timber","amber"]
ti = {t:i for i,t in enumerate(towns)}
P = [[prices[t][g] for g in goods] for t in towns]
CAP, LAST = 20, 8
N = len(goods); NT = len(towns)

@lru_cache(maxsize=None)
def V(d, t, gi):
    if d >= LAST: return P[t][gi]
    return max(P[t][gi], max(V(d+1,u,gi) for u in range(NT) if u != t))

def buy_knapsack(cap_free, gold2, t, d, u):
    # max profit buying any mix, at town t, carrying to u on day d -> d+1
    profit = [V(d+1,u,gi) - P[t][gi] for gi in range(N)]
    cost = P[t]
    dp = [[-10**9]*(gold2+1) for _ in range(cap_free+1)]
    dp[0][0] = 0
    for uu in range(cap_free+1):
        for gg in range(gold2+1):
            if dp[uu][gg] < 0: continue
            for gi in range(N):
                if profit[gi] <= 0: continue
                if uu+1 <= cap_free and gg + cost[gi] <= gold2:
                    nv = dp[uu][gg] + profit[gi]
                    if nv > dp[uu+1][gg+cost[gi]]:
                        dp[uu+1][gg+cost[gi]] = nv
    return max(max(row) for row in dp)

@lru_cache(maxsize=None)
def F(d, t, gold, cargo):
    if d >= LAST:
        return gold + sum(q*P[t][gi] for gi,q in enumerate(cargo))
    best = 0
    for u in range(NT):
        if u == t: continue
        sell_gain = 0; keep = [0]*N
        for gi in range(N):
            cv = V(d+1, u, gi)
            if P[t][gi] >= cv:
                sell_gain += cargo[gi]*P[t][gi]; keep[gi] = 0
            else:
                keep[gi] = cargo[gi]
        gold2 = gold + sell_gain
        cap_free = CAP - sum(keep)
        added = buy_knapsack(cap_free, gold2, t, d, u)
        keep_val = sum(keep[gi]*V(d+1,u,gi) for gi in range(N))
        best = max(best, gold2 + keep_val + added)
    return best

