from itertools import product

PRICES = {
    "Saltby":    {"tea": 16, "grain": 58, "spice": 55, "iron": 49},
    "Oakhaven":  {"tea": 45, "grain": 29, "spice": 22, "iron": 37},
    "Fennick":   {"tea": 15, "grain": 20, "spice": 49, "iron": 59},
    "Rivermouth":{"tea": 12, "grain": 26, "spice": 56, "iron": 37},
}
CAP, LAST = 25, 7
GOODS = ["tea", "grain", "spice", "iron"]
TOWNS = list(PRICES)

def best_actions(town, gold, cargo):
    """Yield (gold, cargo) options for buy/sell combos at this town."""
    for buys in product(*[[0,1] for _ in GOODS]):
        for sells in product(*[[0,1] for _ in GOODS]):
            new = dict(cargo); g = gold
            # buy first
            for gi in range(4):
                if buys[gi] and not sells[gi]:
                    qty = min((CAP - sum(new.values()))//PRICES[town][GOODS[gi]],
                              g//PRICES[town][GOODS[gi]])
                    new[GOODS[gi]] += qty; g -= qty*PRICES[town][GOODS[gi]]
            for gi in range(4):
                if sells[gi] and not buys[gi]:
                    q = new[GOODS[gi]]
                    del new[GOODS[gi]]; g += q*PRICES[town][GOODS[gi]]
            yield (g, tuple(new[k] for k in GOODS))

def search():
    # state: (town, gold, cargo_tuple); day d = number of travels so far
    cur = [("Saltby", 120, (0,0,0,0)), 1]  # (states_list, day)
    best = {}
    day = 1
    states = {"Saltby": [(120, (0,0,0,0))]}
    for day in range(1, LAST+1):
        # buy/sell at current towns
        newstates = {}
        for town, lst in states.items():
            opts = {}
            for g, c in lst:
                for ng, nc in best_actions(town, g, c):
                    opts[(ng, nc)] = True
            newstates[town] = list(opts)
        # gold dominates for same cargo
        states = newstates
        if day == LAST:
            continue
        # travel to each other town
        nxt = {}
        for town, lst in states.items():
            for dest in TOWNS:
                if dest != town:
                    for g, c in lst:
                        key = (g, c)
                        if key not in nxt.get(dest, {}):
                            nxt.setdefault(dest, {})[key] = True
        states = {t: list(d) for t, d in nxt.items()}
    for town, lst in states.items():
        for g, c in lst:
            best[town] = max(best.get(town,0), g)
    return states

states = search()
for town, lst in states.items():
    print(town, "gold options:", sorted(g for g,c in lst), "best:", max(g for g,c in lst))
