CAP=30
GOODS=["fish","wine","amber","silk"]
TOWNS=list(P)

def cargo_vec(g,d):
    return tuple(d[g] for g in GOODS)

def closure(gold, cargo, town):
    """All (gold, cargo) reachable by any buy/sell at town."""
    car=tuple(cargo)
    seen={(gold,car)}; frontier=[(gold,car)]
    while frontier:
        ng=[]
        for (gld, c) in frontier:
            for gi,good in enumerate(GOODS):
                price=P[town][good]; held=c[gi]
                for k in range(1, held+1):          # sell
                    nc=list(c); nc[gi]-=k; nc=tuple(nc)
                    if (gld+k*price, nc) not in seen:
                        seen.add((gld+k*price,nc)); ng.append((gld+k*price,nc))
                room=CAP-sum(c); maxg=gld//price
                for k in range(1, min(room,maxg)+1):# buy
                    nc=list(c); nc[gi]+=k; nc=tuple(nc)
                    if (gld-k*price, nc) not in seen:
                        seen.add((gld-k*price,nc)); ng.append((gld-k*price,nc))
        frontier=ng
    return seen

# dp: (town, cargo) -> max gold at start of current day
dp={("Thornwick",(0,0,0,0)):150}
for day in range(1,8):
    ndp={}
    for (town,cargo),gold in dp.items():
        for (gld,car) in closure(gold,cargo,town):
            for t2 in TOWNS:               # include staying (t2==town)
                key=(t2,car)
                if key not in ndp or gld>ndp[key]:
                    ndp[key]=gld
    dp=ndp

# final: can still trade at current town
best=0; bf=None
for (town,cargo),gold in dp.items():
    for (gld,car) in closure(gold,cargo,town):
        if gld>best:
            best=gld; bf=(town,car,gld)
print("max final gold:", best, "town/cargo/gold:", bf)
