#!/usr/bin/env python3
"""Find the best final gold by enumerating all travel routes and optimal trades."""
from itertools import product

PRICES = {
    "Highcliff": {"fish": 26, "amber": 27, "wine": 20, "salt": 21},
    "Thornwick": {"fish": 43, "amber": 45, "wine": 56, "salt": 39},
    "Dunmere":   {"fish": 54, "amber": 55, "wine": 30, "salt": 19},
    "Greywater": {"fish": 23, "amber": 41, "wine": 32, "salt": 34},
}
CAP = 25
GOODS = ("fish", "amber", "wine", "salt")

def simulate(route, gold=250, start="Highcliff"):
    """route: list of towns visited (first == start). Returns best final gold."""
    towns = route
    cargo = {g: 0 for g in GOODS}
    for i, town in enumerate(towns):
        prices = PRICES[town]
        # sell everything whose price here is >= max price in the rest of the route
        if i < len(towns) - 1:
            for g in GOODS:
                future = [PRICES[t][g] for t in towns[i+1:]]
                if prices[g] >= max(future):
                    gold += cargo[g] * prices[g]
                    cargo[g] = 0
        # buy: integer knapsack over 4 goods, capacity CAP, budget gold
        remaining = CAP - sum(cargo.values())
        # enumerate all buy combos
        best_gold, best_cargo = gold, dict(cargo)
        for qf in range(remaining + 1):
            for qa in range(remaining - qf + 1):
                for qw in range(remaining - qf - qa + 1):
                    for qs in range(remaining - qf - qa - qw + 1):
                        qty = qf + qa + qw + qs
                        if qty > remaining:
                            continue
                        cost = qf*prices["fish"] + qa*prices["amber"] + qw*prices["wine"] + qs*prices["salt"]
                        if cost > gold:
                            continue
                        # objective: final value = gold_left + sum qty*g * eventual sale price
                        # eventual sale price = max over future towns
                        if i < len(towns) - 1:
                            fut = {g: max(PRICES[t][g] for t in towns[i+1:]) for g in GOODS}
                        else:
                            fut = {g: prices[g] for g in GOODS}
                        value = (gold - cost) + qf*fut["fish"] + qa*fut["amber"] + qw*fut["wine"] + qs*fut["salt"]
                        if value > (best_gold + sum(cargo[g]*PRICES[town][g] for g in GOODS)):
                            best_gold = gold - cost
                            best_cargo = {
                                "fish": cargo["fish"] + qf,
                                "amber": cargo["amber"] + qa,
                                "wine": cargo["wine"] + qw,
                                "salt": cargo["salt"] + qs,
                            }
        cargo = best_cargo
        gold = best_gold
    # at the end, sell everything at the final town
    gold += sum(cargo[g] * PRICES[towns[-1]][g] for g in GOODS)
    return gold

def all_routes(max_legs=7):
    routes = [ ["Highcliff"] ]
    current = [ ["Highcliff"] ]
    for _ in range(max_legs):
        nxt = []
        for r in current:
            for t in PRICES:
                if t != r[-1]:
                    nxt.append(r + [t])
        routes.extend(nxt)
        current = nxt
    return routes

best = 0
best_route = None
for r in all_routes():
    g = simulate(r)
    if g > best:
        best, best_route = g, r
print("best final gold:", best)
print("route:", " -> ".join(best_route))
