#!/usr/bin/env python3
"""Optimal final gold via memoized DFS over (day, town, gold, cargo)."""
TOWNS = ("Highcliff", "Thornwick", "Dunmere", "Greywater")
IDX = {t: i for i, t in enumerate(TOWNS)}
PRICES = {
    "Highcliff": {"fish": 26, "amber": 27, "wine": 20, "salt": 21},
    "Thornwick": {"fish": 43, "amber": 45, "wine": 56, "salt": 39},
    "Dunmere":   {"fish": 54, "amber": 55, "wine": 30, "salt": 19},
    "Greywater": {"fish": 23, "amber": 41, "wine": 32, "salt": 34},
}
GOODS = ("fish", "amber", "wine", "salt")
P = {t: [PRICES[t][g] for g in GOODS] for t in TOWNS}
GM = [max(P[t][i] for t in TOWNS) for i in range(4)]  # global best price per good
CAP = 25

from functools import lru_cache

@lru_cache(maxsize=None)
def best_buy(gold, town):
    """Given gold and empty cart at town: return (gold_after, (q0..q3))
    maximizing gold_after + sum q_i*GM_i. Greedy-fill 4th good, enumerate 3."""
    tp = P[town]
    best_val = gold  # buy nothing
    best_q = (0, 0, 0, 0)
    for q0 in range(CAP + 1):
        c0 = q0 * tp[0]
        if c0 > gold:
            break
        for q1 in range(CAP - q0 + 1):
            c01 = c0 + q1 * tp[1]
            if c01 > gold:
                break
            for q2 in range(CAP - q0 - q1 + 1):
                c012 = c01 + q2 * tp[2]
                if c012 > gold:
                    break
                q3 = min(CAP - q0 - q1 - q2, (gold - c012) // tp[3])
                val = (gold - c012 - q3 * tp[3]) + q0*GM[0] + q1*GM[1] + q2*GM[2] + q3*GM[3]
                if val > best_val:
                    best_val = val
                    best_q = (q0, q1, q2, q3)
    return gold - sum(q*tp[i] for i, q in enumerate(best_q)), best_q

